import world from './data/world.json' with {type:'json'};
const boot=startBoot();const app=document.querySelector('#app');let lastPublishCheck=0;
let letters=[],threads=[],privateAlerts=[],letterTyping=false,letterError='',letterBusy=false,letterPeer='',letterLoading=false,typingTimer,arrivalTimer,noticesHandle='',privateLoaded=false;
const suggested=shuffleSuggestions(npcs).map(n=>n.kullanici_adi),seenNotices=new Set(),openedAt=Date.now();
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',search:'m21 21-5-5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',shield:'m12 3 9 4v6c0 5-9 9-9 9S3 18 3 13V7Z',send:'m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',comment:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z',repeat:'m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4M21 13v3a2 2 0 0 1-2 2H3',image:'M3 3h18v18H3ZM3 17l6-6 5 5 3-3 4 4M8 7h.01',more:'M5 12h.01M12 12h.01M19 12h.01',arrow:'M5 12h14m-5-5 5 5-5 5',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3a20 20 0 0 1 0 18 20 20 0 0 1 0-18',logout:'M9 3H3v18h6m5-14 5 5-5 5M9 12h12',close:'m6 6 12 12M6 18 18 6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',key:'M14 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10M9 12H2m3 0v4'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
let user=null,route='',tab='all',limit=20,query='',modal=null,register=false,authOpen=true,composerImage='',letterImage='',imageLoading=false,profileImage='',bannerImage=null,toastTimer,dmSelected=[],renderTimer;
const blockedHandles=()=>new Set((storage.list('users').find(u=>u.handle===user?.handle)?.blockedAccounts||user?.blockedAccounts||[]).map(canonicalHandle));
const person=handle=>{handle=canonicalHandle(handle);const n=npcs.find(n=>n.kullanici_adi===handle);return n?{...n,handle:n.kullanici_adi,name:n.gorunen_ad,race:n.irk,system:n.sistem,job:n.meslek,avatar:asset(n.foto),bio:n.bio,city:n.sehir}:storage.list('users').find(u=>u.handle===handle)||{handle,name:handle||'Bilinmeyen hesap',system:'',bio:''};};
const asset=path=>import.meta.env.BASE_URL+path;
const photo=p=>p.avatar|| (p.foto?new URL(p.foto,document.baseURI).href:'');
function avatar(p,size='',enlarge=false){const src=photo(p);return src?`<img class="avatar ${size}" ${enlarge?`data-image-viewer tabindex="0" role="button" aria-label="${e(p.name)} profil fotoğrafını büyüt"`:""} src="${e(src)}" alt="${e(p.name)}" loading="lazy">`:`<span class="avatar placeholder ${size}">${e((p.name||'?').slice(0,1))}</span>`;}
const faction=system=>world.factions.find(f=>f.systems.includes(system));
function badge(system){return `<span class="system-badge" style="--badge:${faction(system)?.accent||'#9097a5'}">${e(system)}</span>`;}
function notices(){return user?unreadNotifications(storage.list('notifications'),privateAlerts,user.handle):[];}
const unreadCount=()=>notices().filter(n=>!n.readAt).length;
const countBadge=n=>n?`<span class="count-badge">${n>99?'99+':n}</span>`:'';
const nav=(path,ico,label)=>`<a class="nav-item ${route===path?'active':''}" href="#${path}">${icon(ico)}<span>${label}</span>${path==='/notifications'?countBadge(unreadCount()):path==='/messages'?countBadge(threads.reduce((n,t)=>n+t.unread,0)):''}</a>`;

function toast(message){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=route!=='/dm'&&/Firebase|Gemini|\bAPI\b|Failed to fetch|NetworkError|permission-denied/.test(message)?'Hat yanıt vermiyor. Biraz sonra yeniden dene.':message;document.body.append(t);clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),4500);}
function button(action,label,ico='',className=''){const [kind,key]=action.split(/:(.*)/s),busy=storage.interactionBusy(kind,key);const accessible=label||({close:'Kapat',logout:'Çıkış yap',arrow:'Giriş yap'}[ico])||action;return `<button class="${className}" data-action="${action}" aria-busy="${busy}" ${busy?'disabled':''} aria-label="${e(accessible)}">${ico?icon(ico):''}${label}</button>`;}
const richText=formatSocialText;
function relative(t){const mins=Math.max(1,Math.floor((Date.now()-t)/60000));return mins<60?`${mins} dk`:mins<1440?`${Math.floor(mins/60)} sa`:new Date(t).toLocaleDateString('tr-TR',{day:'numeric',month:'short'});}
function feedItems(){let posts=storage.getFeed();if(tab==='following'&&user){const following=storage.list('follows').filter(f=>f.author===user.handle).map(f=>f.target);posts=posts.filter(p=>following.includes(p.author)||p.author===user.handle);}return posts;}
function postCard(p,expanded=false){const author=person(p.author),likes=storage.list('likes').filter(l=>l.postId===p.id),comments=storage.list('comments').filter(c=>c.postId===p.id);const liked=likes.some(l=>l.author===user?.handle);return `<article class="post" id="post-${e(p.id)}"><a class="avatar-link" href="#/profile/${e(p.author)}">${avatar(author)}</a><div class="post-main"><div class="post-header"><a class="display-name" href="#/profile/${e(p.author)}">${e(author.name)}</a>${badge(p.system)}<span class="post-time" title="${new Date(p.createdAt).toLocaleString('tr-TR')}">· ${relative(p.createdAt)}</span>${(p.author===user?.handle||dmUnlocked())?`<button class="icon-button post-menu" aria-label="Paylaşımı sil" data-action="delete:${e(p.id)}">${icon('close',15)}</button>`:''}</div><div class="handle">${e(p.author)} ${author.city?'· '+e(author.city):''}</div>${p.repostOf?`<div class="repost-label">${icon('repeat',13)} Yeniden paylaştı</div>`:''}<div class="post-text">${richText(p.text)}</div>${p.image?`<img class="post-image" tabindex="0" role="button" aria-label="Gönderi görselini büyüt" src="${e(p.image)}" alt="Paylaşıma eklenen görsel" loading="lazy">`:''}${user&&p.system!==user.system?'<span class="packet">HAT PAKETİYLE GELDİ</span>':''}<div class="post-actions"><button aria-label="Yorumları aç" data-action="comments:${e(p.id)}">${icon('comment',18)}<span>${comments.length||''}</span></button><button aria-label="Yeniden paylaş" data-action="repost:${e(p.id)}">${icon('repeat',18)}<span>${storage.getFeed().filter(x=>x.repostOf===p.id).length||''}</span></button><button class="${liked?'liked':''}" aria-label="Beğen" aria-pressed="${liked}" aria-busy="${storage.interactionBusy('like',p.id)}" ${storage.interactionBusy('like',p.id)?'disabled':''} data-action="like:${e(p.id)}">${icon('heart',18)}<span></span></button>${user&&p.author===user.handle?`<button class="like-count" data-action="likers:${e(p.id)}" aria-label="Gonderini begenenleri gor">${likes.length} beğeni</button>`:`<span class="like-count">${likes.length||''}</span>`}<button aria-label="Paylaşım bağlantısını kopyala" data-action="share:${e(p.id)}">${icon('send',17)}</button></div>${expanded?commentList(p,comments):''}</div></article>`;}
function commentList(p,comments){const thread=flattenThread(comments);return `<div class="comments">${thread.map(({comment,depth})=>commentCard(comment,p,depth>0)).join('')}${user?`<form class="comment-form" data-form="comment" data-post="${e(p.id)}"><input name="text" aria-label="Yorumun" placeholder="Sohbete katıl…" maxlength="500" required><button class="icon-button" aria-label="Yorum gönder">${icon('send',18)}</button></form>`:'<p class="muted">Cevap vermek için giriş yap.</p>'}</div>`;}
function commentCard(c,p,nested){const a=person(c.author);return `<div class="comment ${nested?'nested':''}">${avatar(a,'small')}<div><a href="#/profile/${e(c.author)}"><strong>${e(a.name)}</strong></a><p>${richText(c.text)}</p><div class="comment-tools"><span>${relative(c.createdAt)}</span>${user?`<button data-action="reply:${e(c.id)}">Yanıtla</button>`:''}${c.author===user?.handle||dmUnlocked()?`<button data-action="delete-comment:${e(c.id)}">Sil</button>`:''}</div>${modal?.reply===c.id?`<form data-form="comment" data-post="${e(p.id)}" data-parent="${e(c.id)}" class="comment-form"><input name="text" maxlength="500" placeholder="${e(a.name)} için yanıt…" required><button aria-label="Yanıt gönder">${icon('send',16)}</button></form>`:''}</div></div>`;}
function composer(){return `<section class="composer">${avatar(user||{name:'?'})}<form data-form="post"><textarea id="composer-text" name="text" maxlength="750" rows="2" placeholder="${user?'Kümede neler oluyor, '+e(user.name.split(' ')[0])+'?':'Kümede senin hikâyen ne?'}" aria-label="Yeni paylaşım" ${!user?'readonly':''}></textarea>${composerImage?`<div class="attachment"><img src="${e(composerImage)}" alt="Yüklenecek görsel">${button('remove-image','Kaldır')}</div>`:''}<div class="composer-bottom"><div><label class="icon-button file-label" title="Görsel ekle">${icon('image')}<input type="file" id="post-image" accept="image/*" hidden></label><span class="composer-location">${icon('globe',13)} ${e(user?.system||'Qorves ağı')}</span></div><span id="character-count">0 / 750</span><button class="primary small-button" type="submit" ${imageLoading?"disabled":""}>Yayınla ${icon('arrow',16)}</button></div></form></section>`;}
function home(){const posts=feedItems();return `<header class="page-header"><div><span class="eyebrow">KÜMENİN SESİ</span><h1>Ana akış<span class="live-dot"></span></h1></div><span class="date-stamp">SS 214 <i>·</i> AĞ AKTİF</span></header><div class="tabs" role="tablist"><button role="tab" aria-selected="${tab==='all'}" class="${tab==='all'?'selected':''}" data-action="tab:all">Senin için</button><button role="tab" aria-selected="${tab==='following'}" class="${tab==='following'?'selected':''}" data-action="tab:following">Takip ettiklerin</button>${icon('spark',18)}</div>${composer()}<div class="feed-heading"><span>HATLARDAN GELENLER</span><span>En yeni ${icon('more',16)}</span></div>${posts.slice(0,limit).map(p=>postCard(p)).join('')||empty('Henüz bu hatta ses yok.','Birkaç hesabı takip ederek kendi akışını oluştur.')}<div class="load-more">${button('more','Daha fazla yükle','arrow')}</div>`;}
function empty(title,text){return `<div class="empty">${icon('globe',38)}<h2>${title}</h2><p>${text}</p></div>`;}
function profile(handle){handle=canonicalHandle(handle);void storage.openProfile(handle);const p=person(handle),cover=p.bannerImage||(p.banner?asset(p.banner):''),following=storage.list('follows').filter(f=>f.author===handle),followers=storage.list('follows').filter(f=>f.target===handle),followed=storage.list('follows').some(f=>f.author===user?.handle&&f.target===handle);return `<header class="page-header"><div><span class="eyebrow">AĞ KİMLİĞİ</span><h1>Profil</h1></div><a href="#/">${icon('home')}</a></header><div class="profile-cover" ${cover?`data-banner="true" data-image-viewer data-image-src="${e(cover)}" data-image-label="${e(p.name)} · Kapak fotoğrafı" tabindex="0" role="button" aria-label="Kapak fotoğrafını büyüt"`:""} style="${cover?`background-image:linear-gradient(#08101815,#08101835),url(${e(cover)});background-size:cover;background-position:center;`:""}--profile-accent:${e(p.coverColor||faction(p.system)?.accent||'#b7f65d')}"><span>${e(p.system)} / SS 214</span></div><section class="profile-info"><div class="profile-top">${avatar(p,'large',true)}<div class="profile-actions">${p.handle===user?.handle?button('edit-profile','Profili düzenle','user','outline')+button('edit-banner','Kapak fotoğrafını değiştir','image','outline'):button('follow:'+handle,followed?'Takip ediliyor':'Takip et','',followed?'outline':'primary')}${user&&npcs.some(n=>n.kullanici_adi===handle)?button('block:'+handle,blockedHandles().has(handle)?'Engeli kaldır':'Engelle','', 'outline block-account'):''}${handle!==user?.handle&&p.handle?`<a class="outline message-link" href="#/messages/${e(handle)}">${icon('send',17)} Mesaj gönder</a>`:''}</div></div><h1>${e(p.name)}</h1><p class="handle">${e(handle)}</p><p>${e(p.bio)}</p><div class="profile-meta">${badge(p.system)}<span>${e(p.race)}</span><span>${e(p.job)}</span></div><div class="follow-count"><span><strong>${following.length}</strong> takip edilen</span><span><strong>${followers.length}</strong> takipçi</span></div></section><div class="section-title">Paylaşımlar</div>${storage.getFeed().filter(p=>p.author===handle).slice(0,limit).map(p=>postCard(p)).join('')||empty('Hikâye yeni başlıyor.','Bu hesap henüz bir paylaşım yapmadı.')}`;}
function accountCard(p){const followed=storage.list('follows').some(f=>f.author===user?.handle&&f.target===p.handle);return `<div class="account-card"><a href="#/profile/${e(p.handle)}">${avatar(p)}</a><div><a href="#/profile/${e(p.handle)}"><strong>${e(p.name)}</strong></a><span class="handle">${e(p.handle)}</span><span class="muted">${e(p.system)} · ${e(p.race)}</span></div>${p.handle!==user?.handle?`<button class="follow-button ${followed?'is-following':''}" data-action="follow:${e(p.handle)}" aria-label="${e(p.name)} hesabını takip et">${followed?'✓':'+'}</button>`:''}</div>`;}
function searchPage(){const all=[...npcs.map(n=>person(n.kullanici_adi)),...storage.list('users')];const q=normalize(query);const people=all.filter(p=>normalize(p.name+' '+p.handle+' '+p.system+' '+p.race+' '+p.job).includes(q));const posts=q?storage.getFeed().filter(p=>normalize(p.text).includes(q)):[];return `<header class="page-header"><div><span class="eyebrow">YENİ BAĞLANTILAR</span><h1>Keşfet</h1></div>${icon('search')}</header><section class="explore-intro"><h2>Kümenin her köşesinden.</h2><p>Aynı yıldızın altında yaşamıyor olsak da aynı ağdayız.</p><form data-form="search" class="search-field">${icon('search')}<input id="search-main" name="q" value="${e(query)}" placeholder="Hesap, sistem veya #etiket ara" aria-label="Arama"><button class="primary">Ara</button></form><div class="chips">${world.factions.slice(0,6).map(f=>`<button data-action="search:${e(f.systems[0])}">${e(f.name)}</button>`).join('')}</div></section><div class="section-title">${q?'Arama sonuçları':'Ağdaki hesaplar'} <span>${people.length}</span></div>${people.slice(0,limit).map(accountCard).join('')}${posts.length?'<div class="section-title">Paylaşımlar</div>'+posts.slice(0,limit).map(p=>postCard(p)).join(''):''}${!people.length&&!posts.length?empty('Bu frekansta sonuç yok.','Başka bir isim veya etiket dene.'):''}<div class="load-more">${button('more','Daha fazla göster')}</div>`;}
function noticeText(n){return n.kind==='mesaj'?'sana mesaj gönderdi.':n.kind==='takip'?'seni takip etmeye başladı.':n.kind==='beğeni'?(n.count>1?'ve '+(n.count-1)+' kişi paylaşımını beğendi.':'paylaşımını beğendi.'):n.kind==='yanıt'?'sana yanıt verdi.':'paylaşımına yorum yaptı.';}
function noticeRows(rows){return rows.map(n=>{const a=person(n.author);return `<button class="notification ${n.readAt?'':'unread'}" data-action="open-notice:${e(n.id)}">${avatar(a)}<div><strong>${e(a.name)}</strong> ${noticeText(n)}${n.kind==='mesaj'?`<p>${e(n.text.slice(0,90))}</p>`:''}<span>${relative(n.createdAt)}</span></div>${!n.readAt?'<i class="unread-dot"></i>':icon(n.kind==='beğeni'?'heart':n.kind==='mesaj'?'send':'bell',18)}</button>`;}).join('')||empty('Hatların şimdilik sessiz.','Yeni mesajlar ve sana gelen tepkiler burada görünür.');}
function notifications(){return `<header class="page-header"><div><span class="eyebrow">SANA ULAŞANLAR</span><h1>Bildirimler ${countBadge(unreadCount())}</h1></div>${button('read-all','Tümünü okundu say','','outline')}</header>${noticeRows(notices())}`;}
async function openNotice(n){if(!n)return;if(n.source==='private'){await realtime.read(n.peer);privateAlerts=privateAlerts.filter(x=>x.peer!==n.peer);for(const t of threads)if(t.peer===n.peer)t.unread=0;location.hash='/messages/'+n.peer;}else{await storage.readNotifications([n.id]);location.hash=n.postId?'/post/'+n.postId:'/profile/'+n.author;}modal=null;render();void refreshLetters();}
function scanNotices(){if(!user){noticesHandle='';return;}const all=notices();if(noticesHandle!==user.handle){seenNotices.clear();noticesHandle=user.handle;for(const n of all)seenNotices.add(n.id);return;}for(const n of all){if(seenNotices.has(n.id))continue;seenNotices.add(n.id);if(n.readAt||n.createdAt<openedAt-5000)continue;const t=document.createElement('button');t.className='notification-toast';t.innerHTML=`${avatar(person(n.author),'small')}<span><strong>${e(person(n.author).name)}</strong><small>${e(noticeText(n))}</small></span>${icon(n.kind==='mesaj'?'send':'bell',17)}`;t.addEventListener('click',()=>{t.remove();void openNotice(n).catch(err=>toast(err.message));});document.body.append(t);const existing=document.querySelectorAll('.notification-toast');if(existing.length>3)existing[0].remove();setTimeout(()=>t.remove(),7000);}}
function trends(){const counts={};storage.getFeed().forEach(p=>(p.text.match(/#[\p{L}\p{N}_]+/gu)||[]).forEach(t=>counts[t]=(counts[t]||0)+1));return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5);}
function rightRail(){const picks=suggested.filter(h=>h!==user?.handle&&!storage.list('follows').some(f=>f.author===user?.handle&&f.target===h)).slice(0,3).map(person);return `<aside class="right-rail"><form class="rail-search" data-form="search">${icon('search',18)}<input name="q" placeholder="Ağda ara" aria-label="Ağda ara"><kbd>↵</kbd></form><section class="rail-panel"><div class="rail-title"><span>Hat durumu</span>${icon('globe',16)}</div><div class="network-status"><span class="live-dot"></span><strong>Küme ağı çevrimiçi</strong><p>29 kayıtlı yıldız · SS 214</p></div><div class="signal-bars">${Array.from({length:34},(_,i)=>`<i style="height:${10+(i*17%26)}px;--signal-delay:${i*-71}ms;--signal-speed:${900+i%7*150}ms"></i>`).join('')}</div><div class="status-footer"><span>GEÇİT AĞI</span><span>BAĞLANTI AÇIK</span></div></section><section class="rail-panel"><div class="rail-title"><span>Kümede gündem</span>${icon('spark',16)}</div>${trends().map(([t,count],i)=>`<button class="trend" data-action="search:${e(t)}"><span>0${i+1} <small>Qorves gündemi</small></span><strong>${e(t)}</strong><small>${count} paylaşım</small></button>`).join('')||'<p class="muted">Etiketler paylaşımlarla şekillenir.</p>'}${storage.list('events').filter(ev=>ev.expiresAt>Date.now()).slice(0,3).map(ev=>`<div class="event-mini"><span class="eyebrow">HAT BÜLTENİ</span><p>${e(ev.text)}</p></div>`).join('')}</section><section class="rail-panel suggestions"><div class="rail-title"><span>Yeni frekanslar</span>${icon('user',16)}</div>${picks.map(accountCard).join('')}<a class="rail-link" href="#/search">Kümeyi keşfet ${icon('arrow',15)}</a></section><footer class="rail-footer"><span>QORVES SOSYAL</span><p>Geçit hattı üzerinden bağlı.</p><span>SS 214 · HAT PROTOKOLÜ Q/01</span></footer></aside>`;}
function messagesPage(peer){peer=canonicalHandle(peer);
 const p=peer?person(peer):null;letterPeer=p?.handle||'';const isNPC=npcs.some(n=>n.kullanici_adi===peer),peerBlocked=blockedHandles().has(peer);const incoming=letters.filter(m=>m.peer===peer);
 const list=[...threads];if(peer&&!list.some(t=>t.peer===peer))list.unshift({peer,unread:0,last:null});
 return `<header class="page-header"><div><span class="eyebrow">ÖZEL HATLAR</span><h1>Mesajlar ${countBadge(threads.reduce((n,t)=>n+t.unread,0))}</h1></div>${icon('send')}</header>${!user?empty('Önce hesabına bağlan.','Özel konuşmaların kendi hesabında saklanır.'):!realtime.enabled?empty('Hat kapalı.','Biraz sonra tekrar bağlan.'): `${letterError?`<section class="inbox-unlock"><p class="notice">${e(letterError)}</p><form data-form="message-login"><label>Hesap şifren<input type="password" name="password" required autocomplete="current-password"></label><button class="primary">Özel hatları aç</button></form></section>`:''}<section class="inbox-shell ${peer?'has-thread':''}"><aside class="conversation-list" aria-label="Konuşmalar">${list.map(t=>{const a=person(t.peer);return `<a class="conversation ${t.peer===peer?'selected':''} ${t.unread?'unread':''}" href="#/messages/${e(t.peer)}">${avatar(a)}<div><strong>${e(a.name)}</strong><p>${e(t.last?(t.last.sender===user.handle?'Sen: ':'')+(t.last.text||(t.last.image?'Görsel':'')):'Yeni konuşma')}</p></div><span class="conversation-meta">${t.last?`<small>${relative(t.last.createdAt)}</small>`:''}${countBadge(t.unread)}</span></a>`;}).join('')||'<div class="inbox-empty"><span>Henüz bir konuşman yok.</span><p>Bir hesabın profilinden mesaj gönderebilirsin.</p></div>'}</aside>${p?`<section class="conversation-panel"><header class="message-recipient"><a class="inbox-back" href="#/messages" aria-label="Konuşmalara dön">‹</a><a href="#/profile/${e(peer)}">${avatar(p)}</a><div><a href="#/profile/${e(peer)}"><strong>${e(p.name)}</strong></a><p class="handle">${e(peer)}</p></div><a class="message-profile" href="#/profile/${e(peer)}">Profil</a></header><div class="message-history" aria-live="polite">${incoming.map((m,i)=>`${i===0||new Date(m.createdAt).toDateString()!==new Date(incoming[i-1].createdAt).toDateString()?`<span class="message-date">${new Date(m.createdAt).toLocaleDateString('tr-TR',{day:'numeric',month:'long'})}</span>`:''}<div data-key="letter-${e(m.id)}" class="letter ${m.sender===user.handle?'outgoing':'incoming'}"><p>${e(m.text)}</p>${m.image?`<img class="dm-image" tabindex="0" role="button" aria-label="Mesaj görselini büyüt" src="${e(m.image)}" alt="Gönderilen görsel" loading="lazy">`:""}<small>${new Date(m.createdAt).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})}${m.sender===user.handle?' · '+(['failed','quota'].includes(m.state)?'Ulaştı':m.state==='pending'?'İletildi':m.readAt&&m.readAt<=Date.now()?'Görüldü':'İletildi'):''}</small></div>`).join('')||'<div class="thread-start">Bu konuşmada ilk sözü sen söyle.</div>'}${letterTyping?`<div class="typing-indicator"><i></i><i></i><i></i> ${e(p.name.split(' ')[0])} yazıyor…</div>`:''}</div><form data-form="private-message" data-peer="${e(peer)}" class="private-message-form">${letterImage?`<div class="attachment dm-attachment"><img src="${e(letterImage)}" alt="Gönderilecek görsel">${button("remove-dm-image","Kaldır")}</div>`:""}<label class="icon-button file-label" title="Görsel ekle" aria-label="Mesaja görsel ekle">${icon("image",20)}<input type="file" id="dm-image" accept="image/*" hidden></label><textarea id="private-message-text" aria-label="Mesajın" name="text" rows="1" maxlength="1000" placeholder="Bir mesaj yaz…" ${letterImage?"":"required"} ${letterBusy||peerBlocked?'disabled':''}></textarea><button class="send-message" aria-label="Mesajı gönder" ${letterBusy||imageLoading||peerBlocked?'disabled':''}>${icon('send',20)}</button></form>${peerBlocked?'<p class="thread-presence">Bu hesabi engelledin. Engelini profilinden kaldirabilirsin.</p>':''}${isNPC&&!storage.settings.enabled?'<p class="thread-presence">Bu hesap şu an çevrimdışı.</p>':''}</section>`:'<section class="conversation-placeholder"><div class="message-orbit">'+icon('send',30)+'</div><h2>Özel hatların.</h2><p>Bir konuşma seç veya bir profil üzerinden yeni mesaj gönder.</p></section>'}</section>`}`;
}
async function refreshLetters(){
 if(!user||!realtime.enabled||letterLoading)return;letterLoading=true;const peer=location.hash.startsWith('#/messages/')?canonicalHandle(decodeURIComponent(location.hash.split('/')[2]||'')):'';
 try{const data=await realtime.messages(peer);if(peer!==(location.hash.startsWith('#/messages/')?canonicalHandle(decodeURIComponent(location.hash.split('/')[2]||'')):''))return;
  const before=JSON.stringify([letters,threads,privateAlerts,letterTyping,letterError]);letters=data.messages;threads=data.threads||[];privateAlerts=data.alerts||[];letterTyping=data.typing;letterError='';
  if(!privateLoaded){for(const n of privateAlerts)seenNotices.add(n.id);privateLoaded=true;}
  clearTimeout(typingTimer);clearTimeout(arrivalTimer);
  if(peer&&data.arrivalAt){if(data.typingAt>Date.now())typingTimer=setTimeout(()=>{if(letterPeer===peer){letterTyping=true;render();}},data.typingAt-Date.now());arrivalTimer=setTimeout(()=>{letterTyping=false;render();void refreshLetters();},Math.max(0,data.arrivalAt-Date.now())+150);}
  if(peer&&document.visibilityState==='visible'&&privateAlerts.some(n=>n.peer===peer)){await realtime.read(peer);privateAlerts=privateAlerts.filter(n=>n.peer!==peer);for(const t of threads)if(t.peer===peer)t.unread=0;}
  scanNotices();if(before!==JSON.stringify([letters,threads,privateAlerts,letterTyping,letterError]))render();
 }catch(err){if(letterError!==err.message){letterError=err.message;if(location.hash.startsWith('#/messages'))render();}}finally{letterLoading=false;}
}
function dmUnlocked(){return !!storage.settings.dmHash&&sessionStorage.getItem('qorves-dm')===storage.settings.dmHash;}
function dmPage(){if(!dmUnlocked())return `<header class="page-header"><div><span class="eyebrow">OYUN YÖNETİCİSİ</span><h1>Kontrol merkezi</h1></div>${icon('shield')}</header><section class="dm-lock">${icon('key',38)}<h2>${storage.settings.dmHash?'Yönetim kilidi':'DM şifreni belirle'}</h2><p>Simülasyon, olaylar ve ağ ayarları.</p><form data-form="dm-login"><label>DM şifresi<input type="password" name="password" minlength="8" required autocomplete="current-password"></label><button class="primary">${storage.settings.dmHash?'Kilidi aç':'Şifreyi oluştur'}</button></form></section>`;const s=storage.settings,u=storage.usage,usage=u.day===day()?u:{requests:0,posts:0};return `<header class="page-header"><div><span class="eyebrow">OYUN YÖNETİCİSİ</span><h1>Kontrol merkezi</h1></div>${button('dm-lock','Kilitle','shield','outline')}</header><div class="dm-content"><section class="dm-status ${s.enabled?'on':''}"><div><span class="eyebrow">ORTAK SİMÜLASYON</span><h2>${s.enabled&&config.simulationAllowed?'Simülasyon açık':'Simülasyon durduruldu'}</h2><p>Bulut üreticisi · Bilgisayarın kapalıyken de çalışır. Geçmiş ve hafıza korunur.</p></div><button class="switch ${s.enabled?'on':''}" aria-label="Simülasyonu aç veya kapat" aria-pressed="${s.enabled}" aria-busy="${settingsBusy}" ${settingsBusy?'disabled':''} data-action="toggle-simulation"><span></span></button></section>${!config.simulationAllowed?'<div class="notice">Kod üst anahtarı kapalı. Açmak için src/config.js dosyasını değiştir.</div>':''}<div class="usage-grid"><div><strong>${usage.requests||0}<small> / ${s.maxRequests}</small></strong><span>BUGÜNKÜ API İSTEĞİ</span></div><div><strong>${usage.posts||0}<small> / ${s.maxPosts}</small></strong><span>BUGÜNKÜ ÜRETİM</span></div><div><strong>${usage.likes||0}</strong><span>BUGÜNKÜ BEĞENİ</span></div></div><p class="muted">${e((u.status||'').includes('Ortak hat isteği başarısız (429)')?'Firebase kotası doldu; yenilenince otomatik devam edilecek.':u.status||'Henüz üretim yapılmadı.')} · Son otomatik uyandırma: ${u.lastScheduledWake?new Date(u.lastScheduledWake).toLocaleString('tr-TR'):'henüz doğrulanmadı'} · Gün sınırı: İstanbul saati · ${u.pending||0} yayın/etkileşim sırada</p><section class="dm-section"><h2>Ortak veri yedeği</h2><p>${storage.backupStatus.active?(storage.backupStatus.provider==='firebase'?'Firebase ana hat etkin. Sites yedeği hazır.':'Sites yedek hat etkin. Firebase '+(storage.backupStatus.pending?'eşitlemesi bekleniyor ('+storage.backupStatus.pending+' kayıt).':'erişimi kontrol ediliyor.')):(storage.backupStatus.needsRules?'Yedek kurulumunun erişim kuralı onayı bekleniyor.':storage.backupStatus.emergencyPaused?'Ortak kayıt servisi kullanılamıyor. Üretim güvenli biçimde durduruldu.':storage.backupStatus.phase==='copying'?'Eski veriler güvenli biçimde aktarılıyor.':'İlk eşitleme için Firebase kotasının yenilenmesi bekleniyor.')}</p><p class="muted">Kayıtlar tek sıradan geçer. Silinen kayıtlar geri getirilmez; özel konuşmalar ortak kopyaya taşınmaz.</p></section><form id="cloud-settings" class="settings-form" data-form="settings"><h2>Ortak üretim ayarları</h2><label>Gemini modeli<input name="model" value="${e(s.model)}" required pattern="[a-zA-Z0-9.\-]+"></label><div class="form-columns"><label>Aralık (dakika)<input type="number" min="2" max="1440" name="intervalMinutes" value="${s.intervalMinutes}" required></label><label>Günlük API sınırı<input type="number" min="1" max="100" name="maxRequests" value="${s.maxRequests}" required></label><label>Ek DM / oyuncu yanıtı API sınırı<input type="number" min="1" max="200" name="interactiveMaxRequests" value="${s.interactiveMaxRequests||96}" required></label><label>Günlük üretim sınırı<input type="number" min="1" max="5000" name="maxPosts" value="${s.maxPosts}" required></label></div><label class="check"><input type="checkbox" name="postsEnabled" ${s.postsEnabled?'checked':''}> Yeni paylaşımlar üret</label><label class="check"><input type="checkbox" name="repliesEnabled" ${s.repliesEnabled?'checked':''}> Oyunculara cevap ve beğeni üret</label><button class="primary">Ayarları kaydet</button></form><section class="dm-section"><h2>Ortak bulut üretimi</h2>${button("request-cloud-turn","Bir bulut turu iste","spark","primary")}<p class="muted">Bu ayarlar bütün oyuncular için geçerlidir. Üretici zamanı geldiğinde bulutta çalışır; bu sayfanın açık kalması gerekmez. Her tur en fazla 50 metin ve 500 beğeni planlanır.</p><p class="muted">Son başarılı üretim: ${u.lastSuccess?new Date(u.lastSuccess).toLocaleString('tr-TR'):'Henüz yok'}</p><label class="check"><input type="checkbox" name="imageEnabled" form="cloud-settings" ${s.imageEnabled?'checked':''}> Sanal hesaplar nadiren görselli paylaşım yapsın</label><p class="muted">Görseller ücretsiz Cloudflare kotasıyla üretilir. Günlük en fazla 50 deneme; kota dolarsa görsel üretimi durur, metin akışı sürer.</p></section><section class="dm-section"><h2>Hesapları yönet</h2><p class="muted">Sessize alınan sanal hesap yeni üretim yapmaz. Bu tercih bütün ağda geçerlidir.</p><form data-form="npc-mute"><label>Hesap<select name="handle">${npcs.map(n=>`<option value="${e(n.kullanici_adi)}">${e(n.gorunen_ad)} · ${e(n.kullanici_adi)}${s.muted.includes(n.kullanici_adi)?' · sessizde':''}</option>`).join('')}</select></label><button class="outline">Sessiz durumunu değiştir</button></form></section><section class="dm-section"><h2>Kümeye haber ver</h2><p class="muted">Halka açık bir gündem başlat. Sistem seçimi kimlerin etkileneceğini, hesap sayısı olaya özel kaç karakterin tepki vereceğini, süre ise olayın kaç saat aktif kalacağını belirler. Tepkiler sonraki normal üretim turlarına katılır; ek API çağrısı açılmaz.</p><form data-form="event"><label>Olay<textarea name="text" maxlength="500" required placeholder="Halka açık bir olay yaz…"></textarea></label><div class="form-columns"><label>Etkilenen sistem<select name="system"><option value="">Bütün sistemler</option>${world.systems.filter(x=>!world.restrictedSystems.includes(x)).map(x=>`<option>${e(x)}</option>`).join('')}</select></label><label>Tepki verecek hesap<input name="reactions" type="number" min="1" max="20" value="5" required></label><label>Süre (saat)<input name="hours" type="number" min="1" max="168" value="24" required></label></div><button class="primary">Olayı yayınla</button></form>${storage.list('events').map(ev=>`<div class="dm-event"><p>${e(ev.text)}</p><small>${ev.expiresAt>Date.now()?'Aktif':'Süresi doldu'} · ${e(ev.systems?.join(', ')||'Tüm küme')} · ${ev.reacted?.length||0}/${ev.reactions} tepki</small><div>${button('edit-event:'+ev.id,'Düzenle','','outline tiny')}${button('delete-event:'+ev.id,'Sil','','outline tiny')}</div></div>`).join('')}</section><section class="dm-section"><h2>Yedek ve şifre</h2><p class="muted">Yedek API anahtarını veya DM şifresini içermez. İçe aktarma aynı kimlikli oyun kayıtlarının üzerine yazar.</p><div class="button-row">${button('export','JSON yedeği indir','arrow','outline')}<label class="outline file-label">Yedek içe aktar<input id="import-backup" type="file" accept="application/json" hidden></label></div><form data-form="dm-password"><label>Yeni DM şifresi<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><button class="outline">Şifreyi değiştir</button></form></section></div>`;}
function authDialog(edit=false){return `<div class="modal-backdrop"><section class="modal auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button class="icon-button modal-close" data-action="close-modal" aria-label="Kapat">${icon('close')}</button><div class="auth-symbol">Q<span>·</span></div><span class="eyebrow">QORVES KÜME AĞI / SS 214</span><h2 id="auth-title">${edit?'Kimliğini güncelle.':register?'Kümede yerini al.':'Hattına hoş geldin.'}</h2><p class="muted">${edit?'Hikâyen değişir. Kimliğin seninle kalır.':'Hat kimliğinle bağlan. Mesajların ve takip ettiklerin seni bekliyor.'}</p>${!edit?`<div class="auth-tabs">${button('auth-login','Giriş yap','',!register?'selected':'')}${button('auth-register','Kayıt ol','',register?'selected':'')}</div>`:''}<form data-form="${edit?'profile':register?'register':'login'}">${register||edit?`<div class="avatar-upload">${avatar(edit?user:{name:'?'},'large')}<label class="outline file-label">Fotoğraf seç<input id="profile-image" type="file" accept="image/*" hidden></label></div><label>Karakter adı<input id="auth-name" name="name" maxlength="60" value="${e(edit?user.name:'')}" required></label>`:''}<label>Kullanıcı adı<input id="auth-handle" name="handle" value="${e(edit?user.handle:localStorage.getItem('qorves-last-handle')||'')}" placeholder="@karakterin" ${edit?'readonly':''} required autocomplete="username"></label>${register||edit?`<div class="form-columns"><label>Irk<select name="race">${world.races.map(x=>`<option ${edit&&user.race===x?'selected':''}>${e(x)}</option>`).join('')}</select></label><label>Yaşadığı sistem<select name="system">${world.systems.map(x=>`<option ${edit&&user.system===x?'selected':''} ${world.restrictedSystems.includes(x)?'disabled':''}>${e(x)}${world.restrictedSystems.includes(x)?' (yerleşime kapalı)':''}</option>`).join('')}</select></label></div><label>Meslek<input name="job" maxlength="120" value="${e(edit?user.job:'')}" required></label><label>Kısa biyografi<textarea name="bio" maxlength="250" rows="2">${e(edit?user.bio:'')}</textarea></label>${edit?`<div class="banner-upload"><label class="outline file-label">Kapak fotoğrafını seç<input id="banner-image" type="file" accept="image/*" hidden></label>${(bannerImage??user.bannerImage)?`<img src="${e(bannerImage??user.bannerImage)}" alt="Kapak önizlemesi"><button type="button" data-action="remove-banner" class="text-button">Kapak fotoğrafını kaldır</button>`:''}</div><label>Kapak rengi<input name="coverColor" type="color" value="${e(user.coverColor||'#70dce7')}"></label>`:''}`:''}${!edit?`<label>Şifre<input id="auth-password" name="password" type="password" minlength="6" required autocomplete="${register?'new-password':'current-password'}"></label><label class="check"><input name="remember" type="checkbox" checked> Beni hatırla</label>`:''}<button class="primary full-width" type="submit">${edit?'Değişiklikleri kaydet':register?'Ağa katıl':'Bağlan'} ${icon('arrow',18)}</button><p class="form-error" role="alert"></p></form>${!edit?button('browse','Önce ağa göz at','','text-button full-width'):''}<p class="auth-footnote">${storage.mode==='Yerel'?'YEREL DENEME · PAYLAŞIMLAR BU TARAYICIDA':'KÜME AĞI · KİMLİK DOĞRULAMA'}</p></section></div>`;}
function genericModal(){if(!modal)return '';if(modal.type==='likers')return `<div class="modal-backdrop"><section class="modal likers-modal" role="dialog" aria-modal="true" aria-label="Gonderini begenenler"><div class="modal-heading"><h2>Beğenenler</h2>${button('close-modal','','close','icon-button')}</div>${modal.loading?'<p class="muted">Yükleniyor…</p>':modal.error?`<p class="notice">${e(modal.error)}</p>`:(modal.people||[]).map(x=>accountCard(person(x.handle))).join('')||'<p class="muted">Henüz beğeni yok.</p>'}</section></div>`;if(modal.type==='alerts')return `<div class="modal-backdrop"><section class="modal notification-sheet" role="dialog" aria-modal="true" aria-label="Bildirimler"><div class="modal-heading"><h2>Bildirimler ${countBadge(unreadCount())}</h2>${button('close-modal','','close','icon-button')}</div>${noticeRows(notices().slice(0,12))}<a class="all-notifications" href="#/notifications">Tüm bildirimler</a></section></div>`;if(modal.type==='profile')return authDialog(true);if(modal.type==='post'){const p=storage.getFeed().find(p=>p.id===modal.post);return `<div class="modal-backdrop"><section class="modal thread-modal" role="dialog" aria-modal="true" aria-label="Paylaşım ve yorumlar"><div class="modal-heading"><h2>Sohbet</h2>${button('close-modal','','close','icon-button')}</div>${p?postCard(p,true):empty('Paylaşım bulunamadı.','Silinmiş olabilir.')}</section></div>`;}if(modal.type==='event'){const ev=storage.list('events').find(x=>x.id===modal.id);return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Olayı düzenle"><div class="modal-heading"><h2>Olayı düzenle</h2>${button('close-modal','','close','icon-button')}</div><form data-form="edit-event" data-id="${e(ev.id)}"><label>Olay<textarea name="text" maxlength="500" required>${e(ev.text)}</textarea></label><label>Ek süre (saat)<input type="number" name="hours" min="1" max="168" value="24"></label><button class="primary">Kaydet</button></form></section></div>`;}return '';}
function render(){void storage.openComments(modal?.type==='post'?modal.post:location.hash.startsWith('#/post/')?decodeURIComponent(location.hash.split('/')[2]||''):'');if(!location.hash.startsWith('#/profile/'))void storage.openProfile('');const previousRoute=route,oldHistory=document.querySelector('.message-history'),oldScroll=oldHistory?.scrollTop||0,atBottom=!oldHistory||oldHistory.scrollHeight-oldHistory.scrollTop-oldHistory.clientHeight<70;route=decodeURIComponent(location.hash.slice(1)||'/');const editing=document.activeElement;const forms=previousRoute===route?[...app.querySelectorAll('input:not([type=password]):not([type=file]):not([type=checkbox]),textarea')].map((x,i)=>({id:x.id,name:x.name,form:x.closest('form')?.dataset.form,value:x.value})):[];const focusId=editing?.id,selection=editing?.selectionStart;const path=route.split('/').filter(Boolean);let content=path[0]==='messages'?messagesPage(path[1]||''):path[0]==='dm'?dmPage():path[0]==='profile'?profile(path[1]||user?.handle||''):path[0]==='search'?searchPage():path[0]==='notifications'?notifications():path[0]==='post'?(()=>{const p=storage.getFeed().find(p=>p.id===path[1]);if(!p)void storage.loadPost(path[1]);return `<header class="page-header"><h1>Sohbet</h1><a href="#/">Ana akış</a></header>${p?postCard(p,true):empty('Paylaşım bulunamadı.','Bağlantıyı kontrol et.')}`;})():home();patchHTML(app,`<div class="app-shell ${path[0]==='messages'?'is-inbox':''}"><aside class="sidebar"><a class="wordmark" href="#/">qorves<span>·</span><small>SOSYAL</small></a><div class="sidebar-label">KÜME BAĞLANTISI</div><nav>${nav('/','home','Ana akış')}${nav('/search','search','Keşfet')}${nav('/notifications','bell','Bildirimler')}${nav('/messages','send','Mesajlar')}${nav('/profile/'+(user?.handle||''),'user','Profilim')}<div class="nav-divider"></div>${nav('/dm','shield','Yönetim')}</nav>${button('compose','Bir iz bırak','send','primary compose-nav')}<div class="sidebar-bottom"><div class="connection-mode"><i class="live-dot"></i> Küme hattı bağlı</div><div class="sidebar-user">${avatar(user||{name:'?'},'small')}<div><strong>${e(user?.name||'Misafir bağlantısı')}</strong><small>${e(user?.handle||'Hikâyene bağlan')}</small></div>${button(user?'logout':'login','',user?'logout':'arrow','icon-button')}</div></div></aside><main class="main-content">${storage.error?`<div class="notice">Ortak hat geçici olarak kesildi. Yeniden bağlanmayı dene.</div>`:''}${content}</main>${rightRail()}</div><nav class="mobile-nav">${nav('/','home','Akış')}${nav('/search','search','Keşfet')}${nav('/notifications','bell','Bildirim')}${nav('/messages','send','Mesaj')}${nav('/profile/'+(user?.handle||''),'user','Profil')}${nav('/dm','shield','Yönetim')}</nav>${authOpen?authDialog():genericModal()}`);
 const header=app.querySelector('.page-header');if(header&&user&&path[0]!=='dm'&&path[0]!=='notifications'){const bell=document.createElement('button');bell.className='icon-button header-bell';bell.dataset.action='notifications-open';bell.setAttribute('aria-label','Bildirimleri aç');bell.innerHTML=icon('bell',20)+countBadge(unreadCount());header.append(bell);}
 const history=app.querySelector('.message-history');if(history)history.scrollTop=previousRoute!==route||atBottom?history.scrollHeight:oldScroll;
 for(const item of forms){const el=item.id?document.getElementById(item.id):[...app.querySelectorAll('[name]')].find(el=>el.name===item.name&&el.closest('form')?.dataset.form===item.form);if(el&&el.type!=='color'&&el.value!==item.value)el.value=item.value;}
 if(focusId&&document.activeElement!==editing){const el=document.getElementById(focusId);el?.focus({preventScroll:true});if(el&&typeof el.setSelectionRange==='function'&&['text','textarea','search'].includes(el.type))el.setSelectionRange(selection,selection);}
 const ta=document.querySelector('#composer-text');if(ta)document.querySelector('#character-count').textContent=ta.value.length+' / 750';
}
function requireUser(){if(user)return true;authOpen=true;register=false;render();return false;}
