 if(action==='toggle-simulation'){if(settingsBusy)return;settingsBusy=true;render();try{const enabled=!storage.settings.enabled;await storage.saveSettings({enabled});toast(enabled?'Simülasyon açıldı.':'Simülasyon kapatıldı. Paylaşımlar korundu.');}finally{settingsBusy=false;render();}return;}
